using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using QuietCare;

internal static class UpdateTests {
    static int passed,failed;
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex);}}
    static void Reject(Action action){bool rejected=false;try{action();}catch(Exception){rejected=true;}Check(rejected,"Expected rejection");}
    static T Wait<T>(Task<T> task){return task.GetAwaiter().GetResult();}
    static ReleaseVersion Version(string text){ReleaseVersion value;Check(ReleaseVersion.TryParse(text,out value),"Invalid fixture version");return value;}
    static string Sha(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    static UpdateRelease Release(byte[] bytes,string tag="v9.1.0"){return new UpdateRelease{Version=Version(tag),PageUrl=UpdatePolicy.Page(tag),Notes="Release notes",Installer=new UpdateAsset{Url="https://github.com/"+AppInfo.Repository+"/releases/download/"+tag+"/QuietCare-Setup.exe",Size=bytes.Length,Sha256=Sha(bytes)}};}
    static object JsonRelease(string tag,bool preview=false,bool draft=false){var bytes=Encoding.ASCII.GetBytes("MZfixture installer");var release=Release(bytes,tag);return new Dictionary<string,object>{{"tag_name",tag},{"name","Release "+tag},{"body","Plain text <script>not executable</script>"},{"draft",draft},{"prerelease",preview},{"html_url",release.PageUrl},{"assets",new[]{new Dictionary<string,object>{{"name","QuietCare-Setup.exe"},{"size",bytes.Length},{"digest","sha256:"+release.Installer.Sha256},{"browser_download_url",release.Installer.Url}}}}};}
    sealed class Handler : HttpMessageHandler {
        public readonly List<string> Urls=new List<string>();public Func<HttpRequestMessage,HttpResponseMessage> Respond;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancel){cancel.ThrowIfCancellationRequested();Check(request.Headers.Authorization==null,"App sent credentials");Check(request.Headers.UserAgent.ToString().StartsWith("QuietCare/"),"App version User-Agent missing");Urls.Add(request.RequestUri.AbsoluteUri);return Task.FromResult(Respond(request));}
    }
    static string Json(params object[] rows){return new JavaScriptSerializer().Serialize(rows);}
    static HttpResponseMessage Response(byte[] bytes){return new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)};}
    static void Isolated(string name,Action action){string previous=State.DirectoryPath;State.DirectoryPath=Path.Combine(previous,name);try{action();}finally{State.DirectoryPath=previous;}}
    static int Main(string[] args){
        AppContext.SetSwitch("Switch.System.IO.UseLegacyPathHandling",false);AppContext.SetSwitch("Switch.System.IO.BlockLongPaths",false);
        State.DirectoryPath=Path.Combine(args[0],"UpdaterState");Directory.CreateDirectory(State.DirectoryPath);
        Test("Semantic versions compare numbers, previews and build metadata",()=>{Check(Version("v2.10.0").CompareTo(Version("v2.9.9"))>0,"Lexical sort");Check(Version("v2.0.0").CompareTo(Version("v2.0.0-beta.10"))>0,"Stable precedence");Check(Version("v2.0.0-beta.10").CompareTo(Version("v2.0.0-beta.2"))>0,"Numeric preview sort");Check(Version("v1.0.0+meta").CompareTo(Version("v1.0.0"))==0,"Metadata precedence");});
        Test("Invalid and path-shaped version tags are rejected",()=>{foreach(string text in new[]{"../9.0.0","v01.2.3","v1.2","v1.2.3-beta.01","v999999999999.0.0","v1.2.3/evil"}){ReleaseVersion value;Check(!ReleaseVersion.TryParse(text,out value),text);}});
        Test("Release parsing sorts and filters drafts and preview channels",()=>{var feed=Json(JsonRelease("v2.9.0"),JsonRelease("v2.10.0",true),JsonRelease("v3.0.0",false,true));Check(UpdatePolicy.Parse(feed,true).First().Version.Tag=="v2.10.0","Preview absent");Check(UpdatePolicy.Parse(feed,false).Single().Version.Tag=="v2.9.0","Channel filtering");});
        Test("Malformed, oversized and invalid-shaped feeds fail closed",()=>{Reject(()=>UpdatePolicy.Parse("<html>error</html>",true));Reject(()=>UpdatePolicy.Parse("{\"message\":\"error\"}",true));Reject(()=>UpdatePolicy.Parse(new string('x',UpdatePolicy.FeedLimit+1),true));});
        Test("Untrusted release pages and asset URLs cannot become downloads",()=>{var item=(Dictionary<string,object>)JsonRelease("v4.0.0");item["html_url"]="https://evil.example/releases/v4.0.0";Check(UpdatePolicy.Parse(Json(item),true).Count==0,"Foreign page accepted");var release=Release(new byte[]{1,2});foreach(string url in new[]{"http://github.com/x","https://github.com.evil.example/x","https://user@github.com/x",release.Installer.Url+"?other=1",release.Installer.Url+"#other"}){release.Installer.Url=url;Reject(()=>UpdatePolicy.ValidateAsset(release));}});
        Test("Missing digests and implausible installers remain release-page only",()=>{var item=(Dictionary<string,object>)JsonRelease("v4.1.0");var asset=((Dictionary<string,object>[])item["assets"])[0];asset["digest"]=null;Check(UpdatePolicy.Parse(Json(item),true).Single().Installer==null,"Missing digest accepted");var release=Release(new byte[]{1,2});release.Installer.Size=UpdatePolicy.InstallerLimit+1;Reject(()=>UpdatePolicy.ValidateAsset(release));});
        Test("Weekly startup checks are opt-in, bounded and recover from future dates",()=>{DateTime now=DateTime.UtcNow;Check(!UpdatePolicy.Due(false,DateTime.MinValue,now),"Network on by default");Check(UpdatePolicy.Due(true,now.AddDays(-8),now),"Due check absent");Check(!UpdatePolicy.Due(true,now.AddDays(-1),now),"Too frequent");Check(UpdatePolicy.Due(true,now.AddDays(10),now),"Future clock lockout");});
        Test("Update and Care preferences preserve legacy settings and round-trip",()=>Isolated("settings",()=>{var defaults=new Settings();Check(!defaults.CheckUpdatesWeekly&&defaults.IncludePreviewUpdates,"Incorrect defaults");defaults.CheckUpdatesWeekly=true;defaults.IncludePreviewUpdates=false;defaults.ScanCategories="temp,memory";defaults.LastUpdateAttemptUtc=DateTime.UtcNow;defaults.Save();var loaded=Settings.Load();Check(loaded.CheckUpdatesWeekly&&!loaded.IncludePreviewUpdates&&loaded.ScanCategories=="temp,memory","New preferences lost");Check(Math.Abs((loaded.LastUpdateAttemptUtc-defaults.LastUpdateAttemptUtc).TotalSeconds)<1,"Last attempt lost");}));
        Test("Manual preview check uses only the fixed GitHub API endpoint",()=>{var handler=new Handler{Respond=r=>new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Json(JsonRelease("v8.0.0",true)),Encoding.UTF8,"application/json")}};using(var service=new GitHubUpdates(handler)){Check(Wait(service.Check(true,CancellationToken.None)).Version.Tag=="v8.0.0","Missing release");Check(handler.Urls.Single()=="https://api.github.com/repos/"+AppInfo.Repository+"/releases?per_page=30","Wrong API endpoint");}});
        Test("Stable channel handles no published stable release",()=>{var handler=new Handler{Respond=r=>new HttpResponseMessage(HttpStatusCode.NotFound)};using(var service=new GitHubUpdates(handler)){Check(Wait(service.Check(false,CancellationToken.None))==null,"Unexpected stable release");Check(handler.Urls.Single().EndsWith("/releases/latest"),"Wrong stable endpoint");}});
        Test("A rate-limited API falls back only to the fixed project feed",()=>{var handler=new Handler{Respond=r=>r.RequestUri.Host=="api.github.com"?new HttpResponseMessage(HttpStatusCode.Forbidden):new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Json(JsonRelease("v8.0.0",true)))}};using(var service=new GitHubUpdates(handler)){Check(Wait(service.Check(true,CancellationToken.None)).Version.Tag=="v8.0.0","Fallback missing");Check(handler.Urls.Last()=="https://raw.githubusercontent.com/"+AppInfo.Repository+"/main/updates/preview.json","Foreign fallback");}});
        Test("Rate limits, API redirects and cancellation do not report up-to-date",()=>{foreach(var code in new[]{HttpStatusCode.Forbidden,HttpStatusCode.Redirect}){var handler=new Handler{Respond=r=>new HttpResponseMessage(code)};using(var service=new GitHubUpdates(handler))Reject(()=>Wait(service.Check(true,CancellationToken.None)));}var canceled=new CancellationTokenSource();canceled.Cancel();using(var service=new GitHubUpdates(new Handler()))Reject(()=>Wait(service.Check(true,canceled.Token)));});
        Test("Valid installer is hashed, Internet-marked and reverified before launch",()=>Isolated("good",()=>{byte[] bytes=Encoding.ASCII.GetBytes("MZ verified fixture bytes");var release=Release(bytes);var handler=new Handler{Respond=r=>Response(bytes)};using(var service=new GitHubUpdates(handler)){var package=Wait(service.Download(release,null,CancellationToken.None));Check(File.ReadAllBytes(package.Path).SequenceEqual(bytes),"Bytes changed");Check(GitHubUpdates.InternetMark(package.Path).Contains("ZoneId=3"),"No Internet zone mark");bool launched=false;GitHubUpdates.UseVerifiedInstaller(package,path=>{launched=true;Reject(()=>File.WriteAllText(path,"tamper"));});Check(launched,"Verified launch callback absent");var cached=Wait(service.Download(release,null,CancellationToken.None));Check(cached.Path==package.Path&&handler.Urls.Count==1,"Unnecessary download");}}));
        Test("A same-size changed cached installer is never launched",()=>Isolated("tamper",()=>{byte[] bytes=Encoding.ASCII.GetBytes("MZ original");using(var service=new GitHubUpdates(new Handler{Respond=r=>Response(bytes)})){var package=Wait(service.Download(Release(bytes),null,CancellationToken.None));File.WriteAllBytes(package.Path,new byte[bytes.Length]);bool called=false;Reject(()=>GitHubUpdates.UseVerifiedInstaller(package,p=>called=true));Check(!called,"Tampered installer launched");}}));
        Test("Wrong hashes and truncated downloads leave no executable or partial file",()=>Isolated("bad",()=>{byte[] bytes=Encoding.ASCII.GetBytes("MZ expected bytes");var release=Release(bytes);using(var service=new GitHubUpdates(new Handler{Respond=r=>Response(new byte[bytes.Length])}))Reject(()=>Wait(service.Download(release,null,CancellationToken.None)));using(var service=new GitHubUpdates(new Handler{Respond=r=>Response(new byte[2])}))Reject(()=>Wait(service.Download(release,null,CancellationToken.None)));Check(!Directory.EnumerateFiles(State.DirectoryPath,"*",SearchOption.AllDirectories).Any(),"Failed download remains");}));
        Test("Only approved HTTPS GitHub asset redirects are followed",()=>Isolated("redirects",()=>{byte[] bytes=Encoding.ASCII.GetBytes("MZ redirected");var release=Release(bytes);int count=0;using(var service=new GitHubUpdates(new Handler{Respond=r=>{if(count++==0){var response=new HttpResponseMessage(HttpStatusCode.Redirect);response.Headers.Location=new Uri("https://release-assets.githubusercontent.com/fixture?signature=test");return response;}return Response(bytes);}})){Check(File.Exists(Wait(service.Download(release,null,CancellationToken.None)).Path),"Approved redirect failed");}foreach(string url in new[]{"http://release-assets.githubusercontent.com/file","https://evil.example/file","https://release-assets.githubusercontent.com.evil.example/file","https://user@objects.githubusercontent.com/file"}){using(var service=new GitHubUpdates(new Handler{Respond=r=>{var response=new HttpResponseMessage(HttpStatusCode.Redirect);response.Headers.Location=new Uri(url);return response;}})){var different=Release(bytes,"v9.2.0");different.Installer.Sha256=new string('b',64);Reject(()=>Wait(service.Download(different,null,CancellationToken.None)));}}}));
        Test("Redirect loops are bounded and missing Internet marks prevent launch",()=>Isolated("loops",()=>{byte[] bytes=Encoding.ASCII.GetBytes("MZ loop test");var handler=new Handler{Respond=r=>{var response=new HttpResponseMessage(HttpStatusCode.Redirect);response.Headers.Location=new Uri("https://objects.githubusercontent.com/loop");return response;}};using(var service=new GitHubUpdates(handler))Reject(()=>Wait(service.Download(Release(bytes),null,CancellationToken.None)));Check(handler.Urls.Count==5,"Redirect count unbounded");using(var service=new GitHubUpdates(new Handler{Respond=r=>Response(bytes)})){var package=Wait(service.Download(Release(bytes),null,CancellationToken.None));using(var zone=GitHubUpdates.ZoneStream(package.Path,true)){var text=Encoding.ASCII.GetBytes("ZoneId=0");zone.Write(text,0,text.Length);}bool launched=false;Reject(()=>GitHubUpdates.UseVerifiedInstaller(package,p=>launched=true));Check(!launched,"Zone mark was ignored");}}));
        if(args.Contains("--live"))Test("Live GitHub metadata and installer digest verify without execution",()=>Isolated("live",()=>{using(var service=new GitHubUpdates()){var release=Wait(service.Check(true,CancellationToken.None));Check(release!=null&&release.Installer!=null,"No verifiable release");var package=Wait(service.Download(release,null,CancellationToken.None));GitHubUpdates.VerifyFile(package.Path,package.Asset,CancellationToken.None);Console.WriteLine("  LIVE "+release.Version.Tag+" · "+package.Asset.Size+" bytes · SHA-256 verified. Installer not executed.");}}));
        Console.WriteLine("UPDATE RESULT "+passed+" passed / "+failed+" failed");return failed==0?0:1;
    }
}
